def transform(grid):
    """Replace each nonzero source cell by the complement of the source mask."""
    h, w = len(grid), len(grid[0])
    motif = [[0 if value else 1 for value in row] for row in grid]
    out = [[0 for _ in range(w * h)] for _ in range(h * h)]
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color != 0:
                for dr in range(h):
                    for dc in range(w):
                        if motif[dr][dc]:
                            out[r*h + dr][c*w + dc] = color
    return out

if __name__ == '__main__':
    print(transform([[0, 0, 3], [3, 3, 0], [0, 3, 0]]))
